<?php
namespace App\Services;
use App\Models\Etf; use App\Models\EtfDividend; use App\Models\EtfQuote; use Illuminate\Support\Facades\DB;
class EtfDataService { public function __construct(private TwseService $twse,private StrategyService $strategy){} public function sync(): array { $year=(int)now()->year; $rows=$this->twse->dividendRows($year); $seen=[]; foreach($rows as $row){$etf=Etf::updateOrCreate(['code'=>$row['code']],['name'=>$row['name'],'market'=>'TWSE','is_active'=>true,'last_synced_at'=>now()]);$seen[$etf->id]=true;EtfDividend::updateOrCreate(['etf_id'=>$etf->id,'ex_dividend_date'=>$row['ex_dividend_date']],['record_date'=>$row['record_date'],'pay_date'=>$row['pay_date'],'dividend_amount'=>$row['dividend_amount'],'announcement_year'=>$row['announcement_year'],'source_url'=>$row['source_url'],'raw_data'=>$row['raw_data']]);} $candidate=Etf::whereIn('id',array_keys($seen))->whereHas('dividends',fn($q)=>$q->whereBetween('ex_dividend_date',[now()->startOfMonth()->toDateString(),now()->endOfMonth()->toDateString()])->whereDate('ex_dividend_date','>=',today()))->get(); $holding=Etf::whereHas('portfolios',fn($q)=>$q->where('status','holding'))->get(); $targets=$candidate->merge($holding)->unique('id');$quotes=0;$errors=[];foreach($targets as $etf){try{$q=$this->twse->quote($etf->code);EtfQuote::create(['etf_id'=>$etf->id,'price'=>$q['price'],'reference_price'=>$q['reference_price'],'change_amount'=>$q['change_amount'],'change_percent'=>$q['change_percent'],'quote_time'=>$q['quote_time'],'raw_data'=>$q['raw_data']]);$quotes++;}catch(\Throwable $e){$errors[]=$etf->code.': '.$e->getMessage();}} $analyzed=$this->strategy->analyzeAll((float)config('etf.account_amount'));return ['dividends'=>count($rows),'candidates'=>$candidate->count(),'quotes'=>$quotes,'analyzed'=>$analyzed,'errors'=>$errors]; } }
